(30001, 'READING', 27, '{"prompt":"In the first paragraph, the writer suggests that a musician who is ''talented'' is someone:","type":"MULTIPLE_CHOICE","options":{"A":"who is aware of being set apart from other people","B":"whose brain structure is unlike that of other people","C":"who can perform extremely well in early childhood","D":"whose essential skills are more varied than those of ordinary people"}}', 'B'),
(30001, 'READING', 28, '{"prompt":"According to the writer, what is unclear about the findings of Gottfried Schlaug?","type":"MULTIPLE_CHOICE","options":{"A":"Which part of the brain is linked to a particular musical skill.","B":"Which type of musical skill leads to the greatest change in the brain.","C":"Whether a feature of the brain is a cause or an effect of a musical skill.","D":"Whether the acquisition of a musical skill is easier for some people than others."}}', 'C'),
(30001, 'READING', 29, '{"prompt":"According to the writer, what has been established by studies of violin players?","type":"MULTIPLE_CHOICE","options":{"A":"Changes may occur in the brain following violin practice","B":"Left-handed violinists have a different brain structure from other people","C":"A violinist''s hand size is not due to practice but to genetic factors","D":"Violinists are born with brains that have a particular structure"}}', 'A'),
(30001, 'READING', 30, '{"prompt":"According to the writer, findings on the amount of practice done by expert musicians suggest that:","type":"MULTIPLE_CHOICE","options":{"A":"talent may have little to do with expertise","B":"practice may actually prevent the development of talent","C":"talent may not be recognised by teachers","D":"expertise may be related to quality of instruction"}}', 'A'),
